<template><AppShell title="兑换详情" back><StateView :loading="loading" :error="error" :count="item?1:0" @retry="load" /><view v-if="item" class="item-page"><image v-if="rewardImage(item.image)" class="item-image" :src="rewardImage(item.image)" mode="aspectFill" /><view v-else class="item-art">{{item.kind==='BADGE'?'★':'礼'}}</view><view class="card"><text class="muted tiny">{{item.kind==='BADGE'?'活动勋章 · 领取后展示在个人主页':'实物商品 · 兑换后填写收货地址'}}</text><text class="item-title">{{item.title}}</text><view class="row between"><text class="item-price">{{item.pointsCost}} 积分</text><text class="muted tiny">库存 {{item.stock}}</text></view><text class="description">{{item.description}}</text></view><view class="card"><text class="bold">兑换说明</text><text class="description">免费积分不可购买、转让或提现。勋章每人只可持有一枚；实物领取后请在兑换记录填写收货信息。</text></view><button class="ui-button btn" :disabled="busy||item.stock<1" @click="redeem">{{busy?'正在核对兑换…':item.stock<1?'已兑完':'确认兑换'}}</button><button class="ui-button btn outline section" @click="openOrders">查看兑换记录</button></view></AppShell><ConfirmAction v-if="confirmation.open" :key="confirmation.id" :state="confirmation" @answer="answerConfirmation" /></template>
<script setup>
import ConfirmAction from '../../components/ConfirmAction.vue';import {useConfirmation} from '../../lib/confirmation'
const {confirmation,confirm,answerConfirmation}=useConfirmation()
import {ref} from 'vue';import {onLoad,onShow,onUnload} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import StateView from '../../components/StateView.vue';import {request,requireLogin,go,toast,session,loadMe} from '../../lib/api';import {rewardImage,rewardIntent,submitReward,discardRejectedReward} from '../../lib/rewards'
const id=ref(''),item=ref(null),loading=ref(false),error=ref(''),busy=ref(false);let generation=0;onLoad(q=>id.value=q.id);onShow(load);onUnload(()=>generation++)
async function load(){const v=++generation;loading.value=true;error.value='';try{const r=await request('/boost/rewards/goods/'+id.value);if(v===generation)item.value=r}catch(e){if(v===generation)error.value=e.message}finally{if(v===generation)loading.value=false}}
function openOrders(){if(requireLogin())go('rewards/orders')}
async function redeem(){if(busy.value||!requireLogin())return;busy.value=true;const token=session.token,v=generation;let intent;try{if(!await confirm('消耗 '+item.value.pointsCost+' 积分兑换「'+item.value.title+'」？'))return;if(token!==session.token)return;if(!session.user)await loadMe();if(token!==session.token||v!==generation)return;intent=rewardIntent('redeem',id.value,{expectedPointsCost:item.value.pointsCost,expectedRevision:item.value.revision});const r=await submitReward(intent,`/boost/rewards/goods/${id.value}/redeem`);if(v!==generation||token!==session.token)return;toast('兑换完成');go('rewards/order',{id:r.id})}catch(e){if(intent)discardRejectedReward(intent,e);if(token===session.token){toast(e.message);if(e.code===409)load()}}finally{busy.value=false}}
</script>
<style scoped>.item-page{padding:16px}.item-image,.item-art{height:250px;width:100%;border-radius:14px}.item-art{display:flex;align-items:center;justify-content:center;background:#fff2b3;font-size:92px;color:#ae8916}.item-page .card{margin-top:16px}.item-title{display:block;font-size:23px;font-weight:750;margin:10px 0 15px}.item-price{font-size:24px;font-weight:800;color:#9c7000}.description{display:block;font-size:13px;line-height:1.8;white-space:pre-wrap;overflow-wrap:anywhere;margin-top:12px}</style>
